def repeated_substring_pattern(s):
    n = len(s)
    for length in range(1, n // 2 + 1):
        if n % length != 0:
            continue                                              # only lengths that evenly divide n can work
        candidate = s[:length]
        repeated = candidate * (n // length)
        if repeated == s:
            return True
    return False


if __name__ == "__main__":
    s = "abcabcabcabc"
    print(repeated_substring_pattern(s))

