public class Main {
    boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        for (int length = 1; length <= n / 2; length++) {
            if (n % length != 0) continue;                              // only lengths that evenly divide n can work
            String candidate = s.substring(0, length);
            StringBuilder repeated = new StringBuilder();
            for (int i = 0; i < n / length; i++) repeated.append(candidate);
            if (repeated.toString().equals(s)) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        String s = "abcabcabcabc";
        Main solution = new Main();
        System.out.println(solution.repeatedSubstringPattern(s));
    }
}

