def repeated_substring_pattern(s):
    n = len(s)
    lps = [0] * n                                            # longest proper prefix which is also a suffix
    length = 0
    i = 1
    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    candidate_length = n - lps[n - 1]
    return candidate_length != n and n % candidate_length == 0


